import 'package:flutter/material.dart';
void main()=>runApp(Mi9nApp());
class Mi9nApp extends StatelessWidget{
@override Widget build(BuildContext c){return MaterialApp(debugShowCheckedModeBanner:false,home:Home());}}
class Home extends StatefulWidget{@override _HomeState createState()=>_HomeState();}
class _HomeState extends State<Home> with SingleTickerProviderStateMixin{
late TabController t; List<Map> chats=[{"name":"Mama Kasi","msg":"Uphi bhut? 🪶","time":"08:32","u":2},{"name":"Sphe - Gagasi","msg":"Mi9n Blue iyashisa!","time":"08:30","u":1},{"name":"Boi - Lockin","msg":"Sawubona majita","time":"Yesterday","u":0}];
@override void initState(){super.initState(); t=TabController(length:3,vsync:this);}
@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(backgroundColor:Color(0xFF0D47A1),title:Text("Mi9n • Blue Feather"),bottom:TabBar(controller:t,tabs:[Tab(text:"CHATS"),Tab(text:"STATUS"),Tab(text:"CALLS")])),body:TabBarView(controller:t,children:[ListView.builder(itemCount:chats.length,itemBuilder:(c,i){var ch=chats[i]; return ListTile(leading:CircleAvatar(backgroundColor:Color(0xFF0D47A1),child:Text(ch["name"][0])),title:Text(ch["name"],style:TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(ch["msg"]),trailing:Text(ch["time"]),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(name:ch["name"]))));}),Center(child:Text("Status 🪶")),Center(child:Text("Calls"))]),floatingActionButton:FloatingActionButton(backgroundColor:Color(0xFF0D47A1),child:Icon(Icons.chat),onPressed:(){}));}}
class Chat extends StatefulWidget{final String name; Chat({required this.name}); @override _ChatState createState()=>_ChatState();}
class _ChatState extends State<Chat>{List<String> m=["Sawubona!","Mi9n Blue 🪶"]; TextEditingController ctrl=TextEditingController(); @override Widget build(BuildContext c){return Scaffold(appBar:AppBar(backgroundColor:Color(0xFF0D47A1),title:Text(widget.name)),body:Column(children:[Expanded(child:ListView.builder(itemCount:m.length,itemBuilder:(c,i)=>Container(margin:EdgeInsets.all(8),padding:EdgeInsets.all(12),decoration:BoxDecoration(color:i%2==0?Colors.grey[300]:Color(0xFF0D47A1),borderRadius:BorderRadius.circular(12)),child:Text(m[i])))),Row(children:[Expanded(child:TextField(controller:ctrl,decoration:InputDecoration(hintText:"Bhala...",contentPadding:EdgeInsets.all(12)))),IconButton(icon:Icon(Icons.send,color:Color(0xFF0D47A1)),onPressed:(){if(ctrl.text.isNotEmpty){setState((){m.add(ctrl.text); ctrl.clear();});}})])]));}}
